    [1, 3, 4]
    """
    seen = set()
    duplicates = set()
    result = []

    for num in numbers:
        if num in seen and num not in duplicates:
            duplicates.add(num)
        else:
            seen.add(num)

    for num in numbers:
        if num not in duplicates:
            result.append(num)

